-- Table structure for table `producto_tienda_atributo`
--

DROP TABLE IF EXISTS `producto_tienda_atributo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `producto_tienda_atributo` (
  `idproducto_tienda_atributo` bigint unsigned NOT NULL AUTO_INCREMENT,
  `idproducto_tienda` int unsigned NOT NULL,
  `codigo` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `valor_texto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valor_numero` decimal(14,3) DEFAULT NULL,
  `unidad` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confianza` decimal(5,4) NOT NULL DEFAULT '1.0000',
  `fuente` enum('regla','ia','manual') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regla',
  `extraido_en` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idproducto_tienda_atributo`),
  UNIQUE KEY `uk_producto_tienda_atributo` (`idproducto_tienda`,`codigo`),
  KEY `idx_pta_codigo_numero` (`codigo`,`valor_numero`),
  KEY `idx_pta_codigo_texto` (`codigo`,`valor_texto`),
  CONSTRAINT `fk_producto_tienda_atributo_oferta` FOREIGN KEY (`idproducto_tienda`) REFERENCES `producto_tienda` (`idproducto_tienda`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

